    // ══════════════════════════════════════════════════════════════
    // NOTES & REVIEWS
    // ══════════════════════════════════════════════════════════════
    async function loadNotesPage() {
        if (!state.currentProject) return;
        try {
            const data = await api('/projects/' + state.currentProject.id + '/status-board');
            state.statusBoard = data;
            const sceneSelect = document.getElementById('noteSceneSelect');
            sceneSelect.innerHTML = '<option value="">Select scene...</option>' +
                (data.scenes || []).map(s => `<option value="${s.id}">Sc ${s.scene_number} — ${esc(s.location || '')}</option>`).join('');
            document.getElementById('noteShotSelect').innerHTML = '<option value="">Select shot...</option>';
            document.getElementById('notesList').innerHTML = '<p class="text-sm text-muted">Select a scene and shot to view notes.</p>';
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function onNoteSceneChange() {
        const sceneId = document.getElementById('noteSceneSelect').value;
        const scene = (state.statusBoard?.scenes || []).find(s => s.id === sceneId);
        const shotSelect = document.getElementById('noteShotSelect');
        shotSelect.innerHTML = '<option value="">Select shot...</option>' +
            (scene?.shots || []).map(s => `<option value="${s.id}">${esc(s.shot_code)} (${s.status})</option>`).join('');
        document.getElementById('notesList').innerHTML = '';
    }

    async function loadShotNotes() {
        const shotId = document.getElementById('noteShotSelect').value;
        if (!shotId) return;
        try {
            const data = await api('/shots/' + shotId + '/notes');
            const notes = data.notes || [];
            document.getElementById('notesList').innerHTML = notes.length === 0 ?
                '<p class="text-sm text-muted">No notes for this shot.</p>' :
                notes.map(n => `
                    <div class="note-item ${n.resolved ? 'resolved' : ''}">
                        <div class="note-header">
                            <span class="badge ${n.note_type}">${n.note_type}</span>
                            <span class="badge ${n.priority}">${n.priority}</span>
                            <span class="text-sm text-muted">${esc(n.author || 'unknown')}</span>
                            <span class="text-sm text-muted" style="margin-left:auto;">${new Date(n.created_at).toLocaleString()}</span>
                            ${n.resolved ? '<span class="badge completed">Resolved</span>' : `<button class="btn btn-sm btn-secondary" onclick="resolveNote('${n.id}')">Resolve</button>`}
                        </div>
                        <div class="note-content">${esc(n.content)}</div>
                    </div>`).join('');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function showAddNoteModal() {
        if (!document.getElementById('noteShotSelect').value) { setStatus('Select a shot first'); return; }
        showModal('addNoteModal');
    }

    async function addNote() {
        const shotId = document.getElementById('noteShotSelect').value;
        if (!shotId) return;
        const data = getModalData('addNoteModal');
        if (!data.content) return;
        try {
            await api('/shots/' + shotId + '/notes', { method: 'POST', body: JSON.stringify(data) });
            closeModal('addNoteModal');
            clearModal('addNoteModal');
            loadShotNotes();
            setStatus('Note added');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function resolveNote(noteId) {
        try {
            await api('/notes/' + noteId, { method: 'PUT', body: JSON.stringify({ resolved: true }) });
            loadShotNotes();
            setStatus('Note resolved');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function showReviewModal() {
        if (!document.getElementById('noteShotSelect').value) { setStatus('Select a shot first'); return; }
        showModal('reviewShotModal');
    }

    async function submitReview() {
        const shotId = document.getElementById('noteShotSelect').value;
        if (!shotId) return;
        const approved = document.getElementById('reviewDecision').value === 'approve';
        const notes = document.getElementById('reviewNotes').value.trim();
        try {
            await api('/shots/' + shotId + '/review', { method: 'POST', body: JSON.stringify({ approved, notes }) });
            closeModal('reviewShotModal');
            document.getElementById('reviewNotes').value = '';
            loadShotNotes();
            setStatus('Review submitted — shot ' + (approved ? 'approved' : 'rejected'));
        } catch (err) { setStatus('Error: ' + err.message); }
    }
